mkdir -p src/theme && cat > src/theme/storage.ts <<'EOF'
import type {Theme} from '@gravity-ui/uikit';

export const THEME_STORAGE_KEY = 'app-theme';

/** Themes the switcher offers; `system` follows the OS color scheme. */
export const APP_THEMES = ['light', 'dark', 'system'] as const satisfies readonly Theme[];

export type AppTheme = (typeof APP_THEMES)[number];

export const DEFAULT_THEME: AppTheme = 'system';

export function isAppTheme(value: unknown): value is AppTheme {
    return typeof value === 'string' && (APP_THEMES as readonly string[]).includes(value);
}

/** Reads the persisted theme; falls back to the default on a missing/unknown value or blocked storage. */
export function readStoredTheme(): AppTheme {
    try {
        const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
        return isAppTheme(stored) ? stored : DEFAULT_THEME;
    } catch {
        return DEFAULT_THEME;
    }
}

/** Persists the theme; silently ignores blocked storage (private mode, quota, disabled). */
export function writeStoredTheme(theme: AppTheme): void {
    try {
        window.localStorage.setItem(THEME_STORAGE_KEY, theme);
    } catch {
        // storage unavailable — theme stays in memory for this session only
    }
}
EOF
cat > src/theme/AppThemeProvider.tsx <<'EOF'
import * as React from 'react';
import {ThemeProvider} from '@gravity-ui/uikit';

import {
    THEME_STORAGE_KEY,
    type AppTheme,
    isAppTheme,
    readStoredTheme,
    writeStoredTheme,
} from './storage';

interface AppThemeContextValue {
    theme: AppTheme;
    setTheme: (theme: AppTheme) => void;
}

const AppThemeContext = React.createContext<AppThemeContextValue | null>(null);

/**
 * Root theme provider: restores the theme from localStorage on first render
 * (so the page mounts with the right theme), persists every change and keeps
 * other open tabs in sync via the `storage` event.
 */
export function AppThemeProvider({children}: React.PropsWithChildren) {
    const [theme, setThemeState] = React.useState<AppTheme>(readStoredTheme);

    const setTheme = React.useCallback((next: AppTheme) => {
        setThemeState(next);
        writeStoredTheme(next);
    }, []);

    React.useEffect(() => {
        const onStorage = (event: StorageEvent) => {
            if (event.key === THEME_STORAGE_KEY && isAppTheme(event.newValue)) {
                setThemeState(event.newValue);
            }
        };
        window.addEventListener('storage', onStorage);
        return () => window.removeEventListener('storage', onStorage);
    }, []);

    const value = React.useMemo(() => ({theme, setTheme}), [theme, setTheme]);

    return (
        <AppThemeContext.Provider value={value}>
            <ThemeProvider theme={theme}>{children}</ThemeProvider>
        </AppThemeContext.Provider>
    );
}

export function useAppTheme(): AppThemeContextValue {
    const context = React.useContext(AppThemeContext);
    if (!context) {
        throw new Error('useAppTheme must be used within <AppThemeProvider>');
    }
    return context;
}
EOF
